//! ramlib.library's functions: the module loader's one call of its own
//! (SINCE 1.4). What it does otherwise it does by standing in front of
//! exec's OpenLibrary and OpenDevice. The base is the one exec keeps with
//! SetRamLib; the call is exec's, made when a module goes.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/ramlib_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "ramlib.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const UnLoadModule = libraries.lvo(4);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const UnLoadModule = *const fn (*RamLibBase, ?*anyopaque) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const RamLibBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *RamLibBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The segments a library or device was loaded in, unloaded once it has
    /// gone: what its Expunge handed back to exec at its last close or in the
    /// low-memory flush. Segments ramlib did not load are left alone; null
    /// does nothing. Called by exec, after the Expunge returned; it does not
    /// wait, and runs inside AllocMem's low-memory handler too.
    pub fn UnLoadModule(self: *RamLibBase, seg_list: ?*anyopaque) void {
        return libraries.call(self, LVO.UnLoadModule, Fn.UnLoadModule, .{seg_list});
    }
};
